    private static bool NotCcsDefaultIgnorable(in GlyphInfo info) => info.ShaperCategory != CGJ;

    /// <summary>
    /// Marks each syllable's glyphs with a serial and the syllable type, as HarfBuzz's find_syllables_use: the machine reads the
    /// glyphs that are not CGJ, nor a ZWNJ before a mark; a glyph it skips joins the syllable before it.
    /// </summary>
    public static void FindSyllables(LayoutBuffer buffer)
    {
        GlyphInfo[] info = buffer.Info;
        int[] indices = new int[buffer.Len];
        int count = 0;
        for (int i = 0; i < buffer.Len; i++)
        {
            if (!NotCcsDefaultIgnorable(info[i]))
            {
                continue;
            }

            if (info[i].ShaperCategory == ZWNJ)
            {
                bool keep = true;
                for (int j = i + 1; j < buffer.Len; j++)
                {
                    if (NotCcsDefaultIgnorable(info[j]))
                    {
                        keep = !UnicodeProps.IsUnicodeMark(info[j]);
                        break;
                    }
                }

                if (!keep)
                {
                    continue;
                }
            }

            indices[count++] = i;
        }

        int p = 0;
        int pe = count;
        int eof = pe;
        int ts = 0;
        int te = 0;
        int act;
        int cs;

        {
        cs = Start;
        ts = 0;
        te = 0;
        act = 0;
        }



      int syllable_serial = 1;

        {
        int _slen = 0;
        int _trans = 0;
        int _keys = 0;
        int _inds = 0;
        if ( p == pe )
            goto _test_eof;
    _resume:
        switch ( from_state_actions[cs] ) {
        case 3:
        {ts = p;}
        break;
        }

        _keys = cs << 1;
        _inds = index_offsets[cs];

        _slen = key_spans[cs];
        _trans = indicies[_inds + ( _slen > 0 && trans_keys[_keys] <=( info[indices[p]].ShaperCategory) &&
            ( info[indices[p]].ShaperCategory) <= trans_keys[_keys + 1] ?
            ( info[indices[p]].ShaperCategory) - trans_keys[_keys] : _slen )];

    _eof_trans:
        cs = trans_targs[_trans];

        if ( trans_actions[_trans] == 0 )
            goto _again;

        switch ( trans_actions[_trans] ) {
        case 7:
        {te = p+1;}
        break;
        case 16:
        {te = p+1;{ FoundSyllable(info, indices, count, buffer.Len, ts, te, ViramaTerminatedCluster, ref syllable_serial); }}
        break;
        case 14:
        {te = p+1;{ FoundSyllable(info, indices, count, buffer.Len, ts, te, SakotTerminatedCluster, ref syllable_serial); }}
        break;
        case 12:
        {te = p+1;{ FoundSyllable(info, indices, count, buffer.Len, ts, te, StandardCluster, ref syllable_serial); }}
        break;
        case 20:
