    private static void FoundSyllable(GlyphInfo[] info, int[] indices, int count, int len, int ts, int te, int syllableType, ref int serial)
    {
        int end = te < count ? indices[te] : len;
        for (int i = indices[ts]; i < end; i++)
        {
            info[i].Syllable = (byte)((serial << 4) | syllableType);
        }

        serial++;
        if (serial == 16)
        {
            serial = 1;
        }
    }
